#!/usr/bin/env node
'use strict';

// Verifies the TOML-driven team materializer against a temporary config dir.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const SYNC = path.join(ROOT, 'payload', 'mcp', 'sync-team.js');
const MARKER =
  '<!-- Generated by muse-squad sync-team.js; edit muse-squad.toml and re-run the installer. -->';
const RUNNER_MODEL = 'muse-ember-1.0';

function assert(condition, message) {
  if (!condition) throw new Error(`assertion failed: ${message}`);
}

function expectContains(text, needle, label) {
  assert(text.includes(needle), `${label} contains ${JSON.stringify(needle)}`);
}

function run(args, env) {
  return spawnSync(process.execPath, [SYNC, ...args], { encoding: 'utf8', env });
}

function expectRun(args, env) {
  const result = run(args, env);
  assert(
    result.status === 0,
    `sync-team exited ${result.status} (expected 0): ${result.stderr || result.stdout}`
  );
  return result.stdout;
}

function q(value) {
  return JSON.stringify(String(value));
}

function toml({ schema = 1, squadName = 'Test Squad', memoryDir = '.muse-squad', providers, members }) {
  const lines = [`schema = ${schema}`, ''];
  for (const [name, provider] of Object.entries(providers)) {
    lines.push(`[providers.${name}]`, `type = ${q(provider.type)}`);
    if (provider.enabled === false) lines.push('enabled = false');
    if (provider.type === 'http') {
      lines.push(
        `base_url = ${q(provider.base_url)}`,
        `api_key = ${q(provider.api_key || 'unused-key')}`,
        `model = ${q(provider.model)}`
      );
    } else {
      lines.push(`model = ${q(provider.model)}`);
    }
    lines.push(`max_concurrency = ${provider.max_concurrency || 1}`, '');
  }
  lines.push('[squad]', `name = ${q(squadName)}`, `memory_dir = ${q(memoryDir)}`, '');
  for (const [name, member] of Object.entries(members)) {
    lines.push(
      `[squad.${name}]`,
      `primary = ${q(member.primary)}`,
      `fallback = [${member.fallback.map((item) => q(item)).join(', ')}]`,
      `charter = """${member.charter}"""`,
      ''
    );
  }
  return lines.join('\n');
}

function frontmatter(file) {
  const content = fs.readFileSync(file, 'utf8');
  const match = content.match(/^---\n([\s\S]*?)\n---\n/);
  assert(match, `${file} has YAML frontmatter`);
  const fields = {};
  for (const line of match[1].split('\n')) {
    const field = line.match(/^([a-z_]+):\s*(.+)$/);
    if (field) fields[field[1]] = field[2];
  }
  return { content, fields };
}

function assertNoLegacyFields(text, label) {
  for (const word of ['display_name', 'responsibility', '| Role |', 'title:']) {
    assert(!text.includes(word), `${label} must not contain legacy field ${JSON.stringify(word)}`);
  }
}

const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'muse-squad-sync-team-'));
try {
  const configDir = path.join(tempDir, 'config');
  const configFile = path.join(configDir, 'muse-squad.toml');
  const rosterFile = path.join(configDir, 'squad', 'team.md');
  const agentsDir = path.join(configDir, 'agents');
  fs.mkdirSync(agentsDir, { recursive: true });

  const providers = {
    'Native-Primary': { type: 'native', model: 'muse-spark-1.3-contributor', max_concurrency: 2 },
    'Http-Primary': { type: 'http', base_url: 'http://127.0.0.1:1/v1', api_key: 'k', model: 'local-model' },
    'Http-Fallback': { type: 'http', base_url: 'http://127.0.0.1:2/v1', api_key: 'k', model: 'fallback-model' },
    'Native-Fallback': { type: 'native', model: 'muse-wonder-1.0', max_concurrency: 1 },
    'Unused-Provider': { type: 'http', base_url: 'http://127.0.0.1:3/v1', api_key: 'k', model: 'unused-model' }
  };
  const members = {
    atlas: {
      primary: 'Native-Primary',
      fallback: ['Http-Fallback', 'Native-Fallback'],
      charter: 'Lead architecture and dependency order. Keep plans evidence-first and verification-ready. Guardrails: no product edits while planning.'
    },
    runner: {
      primary: 'Http-Primary',
      fallback: [],
      charter: 'Own frontend implementation. Describe visible behavior for every change.'
    },
    solo: {
      primary: 'Native-Primary',
      fallback: [],
      charter: 'Record durable decisions. Append only and never rewrite history.'
    }
  };
  const writeConfig = (config) => fs.writeFileSync(configFile, toml({ ...config, memoryDir: '.muse/qa' }));
  writeConfig({ providers, members });

  const humanAgent = path.join(agentsDir, 'human.md');
  fs.writeFileSync(humanAgent, 'human-written sentinel\n');
  fs.writeFileSync(path.join(agentsDir, 'ghost.md'), `${MARKER}\n# stale ghost\n`);

  const baseArgs = ['--config-dir', configDir];
  const help = expectRun(['--help']);
  expectContains(help, 'Usage: node sync-team.js', '--help output');
  expectContains(help, '--uninstall', '--help output');
  expectContains(help, 'MUSE_CONFIG_DIR, MUSE_SQUAD_CONFIG_FILE', '--help output');
  expectContains(expectRun(['-h']), 'Usage: node sync-team.js', '-h output');

  const first = expectRun(baseArgs);
  expectContains(first, 'sync-team: 3 members', 'first run');
  expectContains(first, 'generated', 'first run');

  const roster = fs.readFileSync(rosterFile, 'utf8');
  expectContains(roster, '# Test Squad', 'roster squad name');
  expectContains(roster, MARKER, 'roster marker');
  expectContains(roster, '| @name | Primary | Fallback | Focus |', 'roster columns');
  expectContains(
    roster,
    '| @atlas | `Native-Primary` (native) | `Http-Fallback`, `Native-Fallback` | Lead architecture and dependency order. |',
    'roster row for atlas'
  );
  expectContains(
    roster,
    '| @runner | `Http-Primary` (http) | (none) | Own frontend implementation. |',
    'roster row for runner'
  );
  expectContains(
    roster,
    '| @solo | `Native-Primary` (native) | (none) | Record durable decisions. |',
    'roster row for solo'
  );
  expectContains(roster, '`.muse-squad/decisions.md`', 'roster decisions path');
  expectContains(roster, '`.muse-squad/history/<name>.md`', 'roster history path');
  expectContains(roster, '<repo>/.muse-squad/', 'roster fixed repo root');
  expectContains(roster, 'muse-squad:memory_status', 'roster memory status tool');
  expectContains(roster, 'muse-squad:memory_init', 'roster memory init tool');
  assert(!roster.includes('.muse/qa'), 'roster ignores the legacy memory_dir override');
  assert(!roster.includes('Unused-Provider'), 'roster has no provider outside member chains');
  assertNoLegacyFields(roster, 'roster');

  const atlas = frontmatter(path.join(agentsDir, 'atlas.md'));
  assert(atlas.fields.name === 'atlas', 'atlas frontmatter name');
  assert(
    atlas.fields.model === 'muse-spark-1.3-contributor',
    'native-primary wrapper pins the native primary model'
  );
  assert(JSON.parse(atlas.fields.description).includes('Invoke as @atlas.'), 'atlas description is JSON quoted');
  expectContains(atlas.content, MARKER, 'atlas wrapper marker');
  expectContains(atlas.content, 'muse-squad:generate_code', 'atlas member-scoped tool');
  expectContains(atlas.content, 'muse-squad:critique_plan', 'atlas member-scoped plan tool');
  expectContains(atlas.content, 'member="atlas"', 'atlas tool scoping');
  expectContains(atlas.content, 'quota, rate limits, or subscription limits', 'atlas native quota retry');
  expectContains(
    atlas.content,
    'Provider chain: `Native-Primary` (native) -> `Http-Fallback` (http) -> `Native-Fallback` (native).',
    'atlas ordered chain with types'
  );
  expectContains(atlas.content, 'Fallback `Native-Fallback` is native model `muse-wonder-1.0`', 'atlas native fallback');
  expectContains(atlas.content, 'servedBy`, `servedProvider`, `servedModel`, `fallbackUsed`, and `attempts', 'atlas meta reporting');
  expectContains(atlas.content, '`.muse-squad/decisions.md`', 'atlas decisions path');
  expectContains(atlas.content, '`.muse-squad/history/atlas.md`', 'atlas history path');
  expectContains(atlas.content, 'muse-squad:memory_status', 'atlas memory status tool');
  expectContains(atlas.content, 'muse-squad:memory_init', 'atlas memory init tool');
  assert(!atlas.content.includes('.muse/qa'), 'wrapper ignores the legacy memory_dir override');
  expectContains(atlas.content, '[atlas | Native-Primary] <action>', 'atlas TUI label');
  assert(!atlas.content.includes('Unused-Provider'), 'atlas wrapper has no provider outside its chain');
  assertNoLegacyFields(atlas.content, 'atlas wrapper');

  const runner = frontmatter(path.join(agentsDir, 'runner.md'));
  assert(runner.fields.model === RUNNER_MODEL, 'http-primary wrapper pins the lightweight runner');
  expectContains(runner.content, `\`model: ${RUNNER_MODEL}\` frontmatter`, 'runner tool-runner note');
  expectContains(runner.content, 'member="runner"', 'runner tool scoping');
  expectContains(runner.content, 'This member has no fallback.', 'runner no-fallback instruction');
  expectContains(runner.content, '[runner | Http-Primary] <action>', 'runner TUI label');

  const solo = frontmatter(path.join(agentsDir, 'solo.md'));
  assert(solo.fields.model === 'muse-spark-1.3-contributor', 'solo pins its native primary');
  expectContains(solo.content, 'This member has no fallback.', 'solo no-fallback instruction');
  expectContains(solo.content, 'member="solo"', 'solo tool scoping');

  assert(!fs.existsSync(path.join(agentsDir, 'ghost.md')), 'stale generated wrapper removed');
  assert(fs.readFileSync(humanAgent, 'utf8') === 'human-written sentinel\n', 'unmarked agent kept');
  assert(!fs.existsSync(path.join(configDir, '.agents')), 'no project override directory');
  assert(
    JSON.stringify(fs.readdirSync(tempDir).sort()) === JSON.stringify(['config']),
    'only global config dir was written'
  );

  const second = expectRun(baseArgs);
  for (const file of [rosterFile, path.join(agentsDir, 'atlas.md'), path.join(agentsDir, 'runner.md'), path.join(agentsDir, 'solo.md')]) {
    expectContains(second, `unchanged  ${file}`, 'second run');
  }
  assert(!/generated|updated/.test(second), 'second run regenerated nothing');
  assert(
    fs.readFileSync(path.join(agentsDir, 'atlas.md'), 'utf8') === atlas.content,
    'unchanged wrapper is byte-identical'
  );

  const updatedMembers = {
    atlas: {
      primary: 'Native-Primary',
      fallback: ['Http-Fallback', 'Native-Fallback'],
      charter: 'Steer architecture and sequencing. Keep plans evidence-first. Guardrails: no product edits while planning.'
    },
    scout: {
      primary: 'Http-Primary',
      fallback: ['Native-Fallback'],
      charter: 'Investigate incidents. Report exact commands and results.'
    }
  };
  writeConfig({ providers, members: updatedMembers });
  fs.writeFileSync(path.join(agentsDir, 'ghost2.md'), `${MARKER}\n# another stale ghost\n`);
  const third = expectRun(baseArgs);
  expectContains(third, 'updated', 'changed config updates files');
  expectContains(third, 'generated', 'new member is generated');
  expectContains(third, 'removed', 'stale generated wrapper is removed');
  assert(!fs.existsSync(path.join(agentsDir, 'runner.md')), 'retired member wrapper removed');
  assert(!fs.existsSync(path.join(agentsDir, 'ghost2.md')), 'stale wrapper removed during sync');
  assert(fs.existsSync(path.join(agentsDir, 'scout.md')), 'new member wrapper generated');
  const updatedRoster = fs.readFileSync(rosterFile, 'utf8');
  expectContains(updatedRoster, 'Steer architecture and sequencing.', 'focus follows edited charter');
  assert(!updatedRoster.includes('@runner'), 'retired member absent from roster');
  const scout = frontmatter(path.join(agentsDir, 'scout.md'));
  assert(scout.fields.model === RUNNER_MODEL, 'new http-primary uses runner model');
  expectContains(
    scout.content,
    'Provider chain: `Http-Primary` (http) -> `Native-Fallback` (native).',
    'scout chain'
  );
  assert(fs.readFileSync(humanAgent, 'utf8') === 'human-written sentinel\n', 'unmarked agent survives updates');

  expectContains(expectRun(['--dir', configDir]), 'unchanged', '--dir alias works');
  expectContains(expectRun(['--config-dir', configDir, '--file', configFile]), 'unchanged', '--file works');
  expectContains(
    expectRun(
      ['--config-dir', configDir, '--file', configFile],
      { ...process.env, MUSE_SQUAD_CONFIG_FILE: path.join(tempDir, 'not-used.toml') }
    ),
    'unchanged',
    'explicit --file wins over env config path'
  );
  expectContains(
    expectRun(['--config-dir', configDir], { ...process.env, MUSE_CONFIG_DIR: configDir }),
    'unchanged',
    'MUSE_CONFIG_DIR is honored'
  );

  // Disabled providers are skipped without editing member chains.
  const disabledProviders = {
    ...providers,
    'Native-Primary': { ...providers['Native-Primary'], enabled: false }
  };
  writeConfig({ providers: disabledProviders, members: updatedMembers });
  expectContains(expectRun(baseArgs), 'updated', 'disabling a provider regenerates files');
  const disabledRoster = fs.readFileSync(rosterFile, 'utf8');
  expectContains(
    disabledRoster,
    '| @atlas | `Native-Primary` (disabled) |',
    'roster marks a disabled primary'
  );
  expectContains(
    disabledRoster,
    '`Http-Fallback`, `Native-Fallback` |',
    'roster keeps unchanged fallbacks'
  );
  const disabledAtlas = frontmatter(path.join(agentsDir, 'atlas.md'));
  assert(disabledAtlas.fields.model === RUNNER_MODEL, 'disabled native primary is not pinned');
  expectContains(
    disabledAtlas.content,
    'Disabled providers are skipped: `Native-Primary`.',
    'wrapper explains the disabled provider'
  );
  expectContains(
    disabledAtlas.content,
    'Provider chain: `Http-Fallback` (http) -> `Native-Fallback` (native).',
    'wrapper chain excludes disabled providers'
  );
  expectContains(
    disabledAtlas.content,
    'Configured primary `Native-Primary` is disabled; `Http-Fallback` is pinned in frontmatter instead.',
    'wrapper explains the pinned replacement'
  );

  const uninstall = expectRun([...baseArgs, '--uninstall']);
  expectContains(uninstall, 'removed', 'uninstall reports removals');
  for (const name of ['atlas', 'scout', 'solo']) {
    assert(!fs.existsSync(path.join(agentsDir, `${name}.md`)), `uninstall removed @${name} wrapper`);
  }
  assert(!fs.existsSync(rosterFile), 'uninstall removed roster');
  assert(fs.existsSync(configFile), 'uninstall keeps config');
  assert(fs.readFileSync(humanAgent, 'utf8') === 'human-written sentinel\n', 'uninstall keeps unmarked agents');

  const missingDir = path.join(tempDir, 'never-created');
  expectContains(expectRun(['--config-dir', missingDir, '--uninstall']), 'absent', 'uninstall tolerates missing dirs');

  writeConfig({ providers, members: updatedMembers });
  expectRun(baseArgs);
  fs.unlinkSync(configFile);
  const noConfigUninstall = expectRun([...baseArgs, '--uninstall']);
  expectContains(noConfigUninstall, 'removed', 'uninstall works without a config file');
  assert(!fs.existsSync(path.join(agentsDir, 'atlas.md')), 'marker-based uninstall removed wrapper');
  assert(!fs.existsSync(rosterFile), 'marker-based uninstall removed roster');
  assert(fs.readFileSync(humanAgent, 'utf8') === 'human-written sentinel\n', 'marker-based uninstall keeps unmarked agents');

  const unknown = run(['--bogus']);
  assert(unknown.status !== 0, 'unknown option is an error');
  expectContains(unknown.stderr, 'unknown option', 'unknown option message');
  const missingValue = run(['--config-dir']);
  assert(missingValue.status !== 0, 'missing option value is an error');
  expectContains(missingValue.stderr, 'requires a value', 'missing value message');
  const missingConfig = run(['--config-dir', missingDir]);
  assert(missingConfig.status !== 0, 'missing config file is an error');
  expectContains(missingConfig.stderr, 'not found', 'missing config message');

  console.log('SYNC TEAM TESTS PASSED');
} finally {
  fs.rmSync(tempDir, { recursive: true, force: true });
}
